System.assertEquals('CartExtension.CartCalculateRuntimeException', new CartExtension.CartCalculateRuntimeException().getTypeName());
System.assertEquals('CartExtension.OptionalNotCheckedException', new CartExtension.OptionalNotCheckedException().getTypeName());
System.assertEquals('CartExtension.PlaceOrderValidationException', new CartExtension.PlaceOrderValidationException('bad cart').getTypeName());
CartExtension.Cart emptyCart = CartExtension.CartTestUtil.createCart();
CartExtension.Cart b2bCart = CartExtension.CartTestUtil.createCart(CartExtension.WebStoreTypeEnum.B2B);
CartExtension.Cart fetchedCart = CartExtension.CartTestUtil.getCart('0aB000000000001AAA');
System.assertNotEquals(null, emptyCart);
System.assertEquals(CartExtension.WebStoreTypeEnum.B2B, b2bCart.webStoreType);
System.assertEquals('0aB000000000001AAA', fetchedCart.id);
CartExtension.BuyerActionDetails buyerDetails = new CartExtension.BuyerActionDetails();
CartExtension.OptionalBuyerActionDetails emptyBuyer = CartExtension.OptionalBuyerActionDetails.empty();
CartExtension.OptionalBuyerActionDetails presentBuyer = CartExtension.OptionalBuyerActionDetails.of(buyerDetails);
System.assertEquals(false, emptyBuyer.isPresent());
System.assertEquals(true, presentBuyer.isPresent());
System.assertEquals(buyerDetails, presentBuyer.get());
CartExtension.CartAdjustmentBasis adjustment = new CartExtension.CartAdjustmentBasis();
CartExtension.OptionalCartAdjustmentBasis emptyAdjustment = CartExtension.OptionalCartAdjustmentBasis.empty();
CartExtension.OptionalCartAdjustmentBasis presentAdjustment = CartExtension.OptionalCartAdjustmentBasis.of(adjustment);
System.assertEquals(false, emptyAdjustment.isPresent());
System.assertEquals(true, presentAdjustment.isPresent());
System.assertEquals(adjustment, presentAdjustment.get());
CartExtension.CartDeliveryGroup deliveryGroup = new CartExtension.CartDeliveryGroup();
CartExtension.OptionalCartDeliveryGroup emptyDelivery = CartExtension.OptionalCartDeliveryGroup.empty();
CartExtension.OptionalCartDeliveryGroup presentDelivery = CartExtension.OptionalCartDeliveryGroup.of(deliveryGroup);
System.assertEquals(false, emptyDelivery.isPresent());
System.assertEquals(true, presentDelivery.isPresent());
System.assertEquals(deliveryGroup, presentDelivery.get());
CartExtension.CartItem item = new CartExtension.CartItem(CartExtension.SalesItemTypeEnum.PRODUCT, deliveryGroup, 'local item');
CartExtension.OptionalCartItem emptyItem = CartExtension.OptionalCartItem.empty();
CartExtension.OptionalCartItem presentItem = CartExtension.OptionalCartItem.of(item);
System.assertEquals(false, emptyItem.isPresent());
System.assertEquals(true, presentItem.isPresent());
System.assertEquals(item, presentItem.get());

